:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --accent: #4cc9f0;
  --accent-dark: #3a9bbf;
  --lamp-off: #3a3a55;
  --lamp-on: #4cc9f0;
  --lamp-on-glow: #4cc9f0aa;
  --focus: #f72585;
  --border: #4a4a6a;
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 32px 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 600;
  text-align: center;
  color: var(--accent);
}

.subtitle {
  text-align: center;
  font-size: 0.95rem;
  color: #a0a0b8;
  margin-top: -8px;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.input-group label {
  font-weight: 500;
  font-size: 0.95rem;
  color: #c0c0d8;
}

input[type="number"] {
  font-family: inherit;
  font-size: 1.25rem;
  padding: 12px 16px;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  transition: border-color 0.2s, box-shadow 0.2s;
  width: 100%;
}

input[type="number"]:hover {
  border-color: var(--accent);
}

input[type="number"]:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-dark);
}

.output-group {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.output-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--bg);
  padding: 12px 16px;
  border-radius: 8px;
  border: 1px solid var(--border);
}

.output-label {
  font-size: 0.9rem;
  color: #a0a0b8;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.output-value {
  font-family: 'SF Mono', 'Fira Code', 'Cascadia Code', monospace;
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--accent);
  letter-spacing: 2px;
}

.lamps-group {
  display: flex;
  justify-content: center;
  gap: 8px;
  flex-wrap: wrap;
}

.lamp {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 2px solid var(--border);
  background: var(--lamp-off);
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, box-shadow 0.2s, transform 0.1s;
  padding: 0;
  flex-shrink: 0;
}

.lamp:hover {
  border-color: var(--accent);
  transform: scale(1.08);
}

.lamp:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.lamp:active {
  transform: scale(0.95);
}

.lamp.on {
  background: var(--lamp-on);
  border-color: var(--lamp-on);
  box-shadow: 0 0 12px var(--lamp-on-glow);
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .lamp {
    width: 34px;
    height: 34px;
  }
  .output-value {
    font-size: 1.1rem;
    letter-spacing: 1px;
  }
}

const decimalInput = document.getElementById('decimalInput');
const binaryOutput = document.getElementById('binaryOutput');
const hexOutput = document.getElementById('hexOutput');
const lamps = document.querySelectorAll('.lamp');

let currentValue = 0;

function updateDisplay(value) {
  currentValue = value;
  decimalInput.value = value;
  binaryOutput.textContent = value.toString(2).padStart(8, '0');
  hexOutput.textContent = '0x' + value.toString(16).toUpperCase().padStart(2, '0');
  lamps.forEach((lamp, index) => {
    const bit = 7 - index;
    const isOn = (value >> bit) & 1;
    lamp.classList.toggle('on', isOn === 1);
    lamp.setAttribute('aria-pressed', isOn === 1 ? 'true' : 'false');
  });
}

function clampAndUpdate(raw) {
  let num = parseInt(raw, 10);
  if (isNaN(num)) num = 0;
  num = Math.min(255, Math.max(0, num));
  updateDisplay(num);
}

decimalInput.addEventListener('input', (e) => {
  clampAndUpdate(e.target.value);
});

decimalInput.addEventListener('blur', (e) => {
  clampAndUpdate(e.target.value);
});

lamps.forEach((lamp) => {
  lamp.addEventListener('click', () => {
    const bit = parseInt(lamp.dataset.bit, 10);
    const newValue = currentValue ^ (1 << bit);
    updateDisplay(newValue);
  });
});

// Initialize
updateDisplay(0);
